"""= Expected Configuration Sections And Parameter Names =
    === In testline_config ===
    [Defaults]
    | _*"caps_qa_config"*_:
    | {
    | 	*"qa"*: "1",
    | 	*"log"*: "my_caps_log.log",
    | 	*"customer"* : "1",
    | 	*"product"* : "1",
    |	*"description"* : "Test Description"
    |	*"purpose"*:"Test Purpose",
    |	*"service"*: "R&D",
    |   *"retention"*: "60",
    |   *"classification"*: "12"
    | },
    |
    """
from taf.ul.trs_e2e_fw.lib.log_scrambling.capsv.caps_interface import CapsInterface


def upload_to_caps(**kwargs):
    """
    This keyword will upload one or more files to CAPS tool, creating a new attachment ID.

    Minimal information needed for upload:
    cert
    customer or customer_cmd
    classification
    product
    description
    purpose
    service
    retention

    *Note*: If productrel is available, it is recommended to include this information as well.
    Some product logs scramble differently based on the product release.

    :param kwargs:
    | *Arguments* | *Default* | *Description* | *Config Ref* |
    | file | Mandatory | full string filepath to snapshot archive to be uploaded to CAPS. |  |
    | config_file | "caps_qa_config" | Configuration file, if not specified "caps_qa_config" will be searched |  |
    |  | Refer to https://nokia.sharepoint.com/sites/CAPS/SitePages/CAPSCLI.aspx for more info |  |`testline_config` |


    :return: string containing CAPS system attachment ID associated with upload.
    :rtype: str

     *Usage* / *Examples* \n
    | Upload To Caps	|	file=file_to_be_uploaded    |   |

    `testline_config` sections:
    "caps_qa_config" (User Configurable name)
    """
    file = kwargs.pop("file")
    return CapsInterface().upload_file_to_caps(file=file, **kwargs)


def is_scramble_ready(**kwargs):
    """
    Return bool indicating whether snapshot associated with `attach_id` has already been scrambled.

    :param kwargs:
    | *Arguments* | *Default* | *Description* | *Config Ref* |
    | attach_id | Mandatory | hash string used to identify uploaded snapshot archive in the CAPS. |  |
    | config_file | "caps_qa_config" | Configuration file, if not specified "caps_qa_config" will be searched |  |
    |  | Refer to https://nokia.sharepoint.com/sites/CAPS/SitePages/CAPSCLI.aspx for more info |  |`testline_config` |

    :return: bool indicating whether scrambled snapshot associated with `attach_id` is ready for download.
    """
    attach_id = kwargs.pop("attach_id")
    caps_list_result = CapsInterface().list_caps_attachment(attach_id=attach_id, **kwargs)
    print("caps_list_result {}".format(caps_list_result))
    return True if caps_list_result.parsed_fields["scrambled_status"] == "ready" else False


def download_scrambled_file_from_caps(**kwargs):
    """
    Download (from CAPS) scrambled snapshot (associated with `attach_id`) to the folder pointed by `destination_dirpath`

    :param kwargs:
    | *Arguments* | *Default* | *Description* | *Config Ref* |
    | attach_id | Mandatory | hash string used to identify uploaded snapshot archive in the CAPS. |  |
    | config_file | "caps_qa_config" | Configuration file, if not specified "caps_qa_config" will be searched |  |
    |  | Refer to https://nokia.sharepoint.com/sites/CAPS/SitePages/CAPSCLI.aspx for more info |  |`testline_config` |
    | destination_dirpath | "execution_logs/" | full directory path string for downloaded snapshots destination |  |
    |  |  | directory. |  |

    :return: object containing two attributes:
             - `archive_filepath` - string containing filepath of downloaded archive file,
             - `decryption_key` - string containing decryption key needed to unpack encrypted archive.
    """
    attach_id = kwargs.pop("attach_id")
    return CapsInterface().download_scrambled_file(attach_id=attach_id, **kwargs)


def download_encrypted_file_from_caps(**kwargs):
    """
    Download (from CAPS) encrypted snapshot (associated with `attach_id`) to the folder pointed by `destination_dirpath`

    :param kwargs:
    | *Arguments* | *Default* | *Description* | *Config Ref* |
    | attach_id | Mandatory | hash string used to identify uploaded snapshot archive in the CAPS. |  |
    | config_file | "caps_qa_config" | Configuration file, if not specified "caps_qa_config" will be searched |  |
    |  | Refer to https://nokia.sharepoint.com/sites/CAPS/SitePages/CAPSCLI.aspx for more info |  |`testline_config` |
    | destination_dirpath | "execution_logs/" | full directory path string for downloaded snapshots destination |  |
    |  |  | directory. |  |

    :return: object containing two attributes:
             - `archive_filepath` - string containing filepath of downloaded archive file,
             - `decryption_key` - string containing decryption key needed to unpack encrypted archive.
    """
    attach_id = kwargs.pop("attach_id")
    return CapsInterface().download_encrypted_file(attach_id=attach_id, **kwargs)


def list_attachments(**kwargs):
    """
    List information (status, download links etc.) of uploaded snapshot associated with `attach_id`.

    :param kwargs:
    | *Arguments* | *Default* | *Description* | *Config Ref* |
    | attach_id | Mandatory | hash string used to identify uploaded snapshot archive in the CAPS. |  |
    | config_file | "caps_qa_config" | Configuration file, if not specified "caps_qa_config" will be searched |  |
    |  | Refer to https://nokia.sharepoint.com/sites/CAPS/SitePages/CAPSCLI.aspx for more info |  |`testline_config` |

    :return: object containing the following attributes:
             - exit_code - exit code integer representing status of the
                           operation result.
             - raw_output - non-processed log output of the operation.
             - parsed_fields - values of interest parsed from `raw_output`.
    """
    attach_id = kwargs.pop("attach_id")
    return CapsInterface().list_caps_attachment(attach_id=attach_id, **kwargs)


def delete_attachments(**kwargs):
    """
    Delete from CAPS uploaded snapshot (both encrypted and scrambled variants) associated with `attach_id`.

    Please take note that due to the limitations of the CAPS system, upon
    running this method, snapshot associated with input ID is just marked
    for deletion, not deleted outright. The CAPS itself performs 'cleanup'
    operation once a day at an unspecified time.

    :param kwargs:
    | *Arguments* | *Default* | *Description* | *Config Ref* |
    | attach_id | Mandatory | hash string used to identify uploaded snapshot archive in the CAPS. |  |
    | config_file | "caps_qa_config" | Configuration file, if not specified "caps_qa_config" will be searched |  |

    :return NA
    :rtype: NA

    """
    attach_id = kwargs.pop("attach_id")
    caps_delete_result = CapsInterface().delete_caps_attachment(attach_id=attach_id, **kwargs)
    if caps_delete_result.parsed_fields["attach_id"] != attach_id:
        raise Exception("Expected return information couldn't be found in output.{}/{}".format(
            caps_delete_result.exit_code, caps_delete_result.raw_output))

def verify_scrambling(**kwargs):
    """
    Verifies that no same ips are present in actual and scrambled folder

    :param kwargs:
    | *Arguments* | *Default* | *Description* | *Config Ref* |
    | actual_zip | Mandatory | The Folder name of actual unscrambled zip |  |
    | scrambled_zip | Mandatory | The Folder name of scrambled zip |  |
    | folder_path | | The folder path at which both the zip folders are present |  |

    :returns: Prints the list of similarIPs if present

    """
    return CapsInterface().verify_scrambling( **kwargs)


